import React from 'react';
import { Navigate, Outlet } from 'react-router-dom';

// Import your access level constants
import { ACCESS_LEVEL_GUEST } from "../config/global_constants";

const LoggedInRoute = () => {
    // Get the user's access level from localStorage
    const accessLevel = parseInt(localStorage.getItem("accessLevel"), 10) || ACCESS_LEVEL_GUEST;

    return accessLevel > ACCESS_LEVEL_GUEST ? <Outlet /> : <Navigate to="/MainPage" />;
};

export default LoggedInRoute;
